package com.srent.chat;
import com.srent.common.ApiException; import com.srent.room.*; import com.srent.security.CurrentUser; import com.srent.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*; import java.util.regex.Pattern;
@RestController @RequestMapping("/api/v1/conversations") @RequiredArgsConstructor
public class ChatController {
    private static final Pattern CONTACT=Pattern.compile("(?i)([\\w.+-]+@[\\w.-]+\\.[a-z]{2,}|(?:\\+?84|0)[ .-]?[0-9][0-9 .-]{7,12})"); private final ConversationRepository conversations; private final MessageRepository messages; private final RoomRepository rooms; private final UserRepository users;
    public record CreateRequest(@NotNull UUID roomId){} public record ConversationResponse(UUID id,UUID roomId,String roomTitle,UUID studentId,UUID landlordId,Instant updatedAt,String maskingNotice){static ConversationResponse from(Conversation c){return new ConversationResponse(c.getId(),c.getRoom().getId(),c.getRoom().getTitle(),c.getStudent().getId(),c.getLandlord().getId(),c.getUpdatedAt(),"Bộ lọc chỉ giảm hiển thị thông tin liên hệ, không bảo đảm ngăn trao đổi ngoài nền tảng");}}
    public record MessageRequest(@NotBlank @Size(max=2000) String content){} public record MessageResponse(UUID id,UUID senderId,String content,boolean masked,Instant createdAt){static MessageResponse from(Message m){return new MessageResponse(m.getId(),m.getSender().getId(),m.getContent(),m.isMasked(),m.getCreatedAt());}}
    @PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('STUDENT')") @Transactional public ConversationResponse create(@Valid @RequestBody CreateRequest q){var r=rooms.findById(q.roomId()).orElseThrow(()->ApiException.notFound("Phòng"));if(r.getApprovalStatus()!=Room.ApprovalStatus.APPROVED)throw ApiException.notFound("Phòng");UUID uid=CurrentUser.id(),lid=r.getProperty().getOwner().getId();if(uid.equals(lid))throw ApiException.badRequest("SELF_CONVERSATION","Không thể tự nhắn tin");var c=conversations.findByRoomIdAndStudentIdAndLandlordId(r.getId(),uid,lid).orElseGet(()->{var x=new Conversation();x.setRoom(r);x.setStudent(users.getReferenceById(uid));x.setLandlord(r.getProperty().getOwner());return conversations.save(x);});return ConversationResponse.from(c);}
    @GetMapping public List<ConversationResponse> list(){return conversations.findForUser(CurrentUser.id()).stream().map(ConversationResponse::from).toList();}
    @GetMapping("/{id}/messages") public Page<MessageResponse> history(@PathVariable UUID id,@PageableDefault(size=50) Pageable p){access(id);return messages.findAllByConversationIdOrderByCreatedAtAsc(id,p).map(MessageResponse::from);}
    @PostMapping("/{id}/messages") @ResponseStatus(HttpStatus.CREATED) @Transactional public MessageResponse send(@PathVariable UUID id,@Valid @RequestBody MessageRequest q){var c=access(id);String masked=CONTACT.matcher(q.content()).replaceAll("[thông tin liên hệ đã ẩn]");var m=new Message();m.setConversation(c);m.setSender(users.getReferenceById(CurrentUser.id()));m.setMasked(!masked.equals(q.content()));m.setContent(masked);messages.save(m);return MessageResponse.from(m);}
    @PatchMapping("/{id}/read") @Transactional @ResponseStatus(HttpStatus.NO_CONTENT) public void read(@PathVariable UUID id){var c=access(id);if(c.getStudent().getId().equals(CurrentUser.id()))c.setStudentLastReadAt(Instant.now());else c.setLandlordLastReadAt(Instant.now());}
    private Conversation access(UUID id){var c=conversations.findById(id).orElseThrow(()->ApiException.notFound("Cuộc trò chuyện"));UUID u=CurrentUser.id();if(!c.getStudent().getId().equals(u)&&!c.getLandlord().getId().equals(u))throw ApiException.forbidden("Bạn không thuộc cuộc trò chuyện này");return c;}
}
